   "titolo": "Liverpool-Manchester City, la rivalità che domina la Premier League",
   "orig": "Liverpool vs Man City: the top five clashes between Premier League giants",
   "lead": "Liverpool e Manchester City si affrontano domenica in uno dei confronti più attesi della Premier League, scontro diventato negli ultimi anni la rivalità dominante del campionato inglese. Al Jazeera ripercorre i cinque precedenti più significativi tra le due squadre, mentre altre testate guardano al contesto più ampio del torneo: il Manchester United ha pareggiato 1-1 in casa contro il Tottenham nonostante l'espulsione di Rodrigo Bentancur, e si discute delle possibili conseguenze per il Manchester City della contestazione della sentenza Uefa sulle violazioni finanziarie imposte dalla Premier League.",
