   "id": "z5f5af19f",
   "sez": "salute",
   "titolo": "Giornata mondiale della salute mentale, casi raddoppiati dal 1990",
   "orig": "Sos Salute Mentale, Giornata mondiale",
   "lead": "In occasione della Giornata mondiale della salute mentale, i dati diffusi segnalano che i casi sono raddoppiati tra il 1990 e il 2023, con un aumento particolarmente marcato tra i giovani. In Italia, secondo l'Ansa, circa otto milioni di persone soffrono di disturbi che vanno dall'ansia a condizioni più gravi, ma solo 850mila sono seguite dal servizio pubblico; vengono inoltre richiamati il ruolo dei social media, la ricerca scientifica, i fondi in arrivo e il peso delle parole usate per parlare di salute mentale.",
   "more": [
    "La Giornata mondiale della salute mentale si celebra ogni anno il 10 ottobre per sensibilizzare sull'importanza del benessere psicologico e sull'accesso alle cure, in un contesto in cui ansia, depressione e altri disturbi risultano in crescita a livello globale, specie tra i più giovani."
   ],
