   "sez": "salute",
   "titolo": "Brexit, Covid e mini-bilancio Truss hanno danneggiato la salute mentale nel Regno Unito",
   "orig": "Covid, Brexit and Liz Truss mini-budget led to lasting decline in mental health, study finds",
   "lead": "Uno studio britannico ha individuato cinque eventi degli ultimi dieci anni — tra cui la Brexit, il mini-bilancio di Liz Truss, l'invasione russa dell'Ucraina e i primi due lockdown per il Covid — che avrebbero causato un deterioramento serio e duraturo della salute mentale della popolazione del Regno Unito. I ricercatori hanno misurato l'impatto attraverso il numero di persone con diagnosi di depressione e ansia, registrando forti impennate di disagio psicologico in corrispondenza di ciascuno di questi shock.",
   "more": [
    "Gli studi epidemiologici sulla salute mentale collettiva analizzano come eventi politici, economici o sanitari di portata nazionale influenzino i livelli di ansia e depressione nella popolazione, spesso tramite dati su diagnosi cliniche e prescrizioni di farmaci."
   ],
