   "sez": "mondo",
   "titolo": "Il Nobel per la pace a Navi Pillay accende il dibattito sul diritto internazionale",
   "orig": "Le Nobel de Navi Pillay met à nu la bataille autour du droit international",
   "lead": "L'attribuzione del premio Nobel per la pace 2026 alla giurista sudafricana Navi Pillay, ex Alta Commissaria delle Nazioni Unite per i diritti umani, ha acceso un duro confronto sul diritto internazionale. Pillay ha presieduto la commissione d'inchiesta Onu che nel settembre 2025 ha concluso che Israele ha commesso un genocidio nella Striscia di Gaza, e la decisione del comitato norvegese ha provocato una reazione molto critica da parte delle autorità israeliane, oltre a un attacco pubblico del presidente statunitense Donald Trump durante un comizio a Syracuse, nello stato di New York.",
   "more": [
    "Navi Pillay è una giurista sudafricana che ha guidato l'Alto Commissariato Onu per i diritti umani ed è stata giudice di tribunali internazionali; la commissione d'inchiesta Onu che ha presieduto si è occupata di documentare presunte violazioni commesse durante il conflitto a Gaza."
   ],
