   "id": "za7395685",
   "sez": "spazio",
   "titolo": "Il Nobel per la Fisica 2026 premia la scoperta dei neutrini cosmici ad alta energia",
   "orig": "APOD: 2026 October 11 – Ice Fishing for Cosmic Neutrinos",
   "lead": "Il premio Nobel per la Fisica 2026 è stato assegnato al fisico belga Francis Halzen per il suo lavoro sul rivelatore IceCube, che osserva i neutrini, particelle elusive provenienti dallo spazio. Il riconoscimento, annunciato tra i premi Nobel di quest'anno, celebra l'idea alla base del progetto che ha permesso di individuare questi neutrini cosmici ad alta energia. La notizia viene ripresa anche dall'immagine astronomica del giorno della NASA, dedicata proprio alla ricerca di neutrini nei ghiacci antartici.",
   "more": [
    "IceCube è un osservatorio di neutrini costruito nei ghiacci dell'Antartide, che utilizza sensori sepolti in profondità per rilevare le rarissime interazioni di queste particelle subatomiche con la materia, aprendo una nuova finestra di osservazione sull'universo."
   ],
