   "orig": "Calls for better Dunedin dermatology services after 'debilitating' rare cancer went undiagnosed",
   "lead": "Mark Baxter ha lanciato una petizione per chiedere servizi pubblici di dermatologia permanenti e in presenza a Dunedin e nella regione di Southern, in Nuova Zelanda. L'iniziativa nasce dopo che un raro tumore definito 'debilitante' non è stato diagnosticato in tempo per mancanza di adeguata assistenza dermatologica. Lo riferisce RNZ.",
