   "id": "z67989478",
   "sez": "organizzazioni",
   "titolo": "Il Vaticano ricorda che solo sette ordini equestri sono riconosciuti dalla Santa Sede",
   "orig": "Ordini equestri, solo sette quelli riconosciuti dalla Santa Sede",
   "lead": "La Segreteria di Stato vaticana ha diffuso una nota, il 10 ottobre, in cui precisa che la Santa Sede riconosce soltanto i propri cinque ordini, oltre al Sovrano Militare Ordine di Malta e all'Ordine Equestre del Santo Sepolcro di Gerusalemme. Il documento chiarisce che non viene attribuito alcun valore ai diplomi cavallereschi rilasciati da sodalizi non riconosciuti e che è ritenuto inopportuno l'uso di chiese e cappelle per le cosiddette 'cerimonie di investitura' legate a tali ordini.",
   "more": [
    "Gli ordini equestri sono istituzioni di origine storica, spesso legate a tradizioni cavalleresche o religiose, che conferiscono titoli onorifici; nel tempo sono nati numerosi sodalizi non ufficiali che si richiamano a tali tradizioni senza alcun riconoscimento da parte delle autorità competenti."
   ],
