   "titolo": "L'Estonia discute del peso del debito pubblico tra crescita e inflazione",
   "orig": "Raul Eamets: Estonia is haunted by an overblown debt‑burden specter",
   "lead": "L'economista Raul Eamets sostiene che il dibattito estone sul debito pubblico sia sovradimensionato, perché non tiene conto di due fattori che influenzano il quadro complessivo: la crescita economica e l'aumento dei prezzi. Nello stesso giorno, il Financial Times riporta che in Cina il crescente debito pubblico limita lo spazio per nuove misure di stimolo economico, poiché il peso crescente degli interessi riduce il margine di manovra per rilanciare la domanda interna.",
   "more": [
    "Il rapporto debito/PIL è un indicatore usato per valutare la sostenibilità delle finanze pubbliche di un paese; la sua interpretazione dipende fortemente dal ritmo di crescita economica e dal livello di inflazione, che possono alleggerire o aggravare il peso reale del debito."
   ],
