   "titolo": "Smontare l'impalcatura delle cellule nervose alleva il dolore cronico nei topi",
   "orig": "Breaking down nerve-cell scaffold relieves chronic pain in mice",
   "lead": "Uno studio pubblicato su Nature mostra che la rottura di una struttura di sostegno delle cellule nervose, chiamata scaffold, riduce il dolore cronico in modelli murini. Lo stesso filone di ricerca è richiamato da ScienceDaily, che descrive un dispositivo minuscolo e iniettabile capace di controllare l'attività nervosa senza intervento chirurgico, batterie o fili, alimentato in modalità wireless dall'esterno del corpo, con risultati promettenti nei test preliminari per il trattamento del dolore cronico e dei disturbi del movimento.",
   "more": [
    "Il dolore cronico è una condizione difficile da trattare con i farmaci tradizionali; la ricerca su dispositivi e tecniche che agiscono direttamente sulle cellule nervose punta a offrire alternative meno invasive rispetto ai trattamenti farmacologici convenzionali."
   ],
