   "lead": "Lo scrittore texano Joe R. Lansdale, autore tra l'altro della 'Trilogia del drive-in', ha criticato duramente l'idea di trasmettere in diretta una pena di morte negli Stati Uniti, definendola una barbarie paragonabile ai giochi del Colosseo. In un'intervista a la Repubblica, lo scrittore ipotizza che chi propone questa trasmissione voglia dimostrare quanto sia duro e conservatore.",
