   "id": "zbb27f5f7",
   "sez": "cucina",
   "titolo": "Come il dado ha cambiato la cucina delle famiglie italiane",
   "orig": "Quando il dado cambiò la vita delle italiane. E inventò un nuovo sapore di casa",
   "lead": "Nato per far risparmiare tempo in cucina, il dado da brodo è entrato gradualmente nelle ricette delle famiglie italiane fino a diventare uno dei sapori associati oggi alla cucina casalinga. Gambero Rosso ripercorre questa storia, che racconta anche un pezzo della vicenda delle donne italiane nel dopoguerra, tra lavoro domestico e trasformazioni sociali. Lo riferisce Gambero Rosso.",
   "more": [
    "Il dado da brodo è un concentrato di sapori disidratato, usato per insaporire rapidamente zuppe e pietanze senza la lunga preparazione del brodo tradizionale. La sua diffusione nel dopoguerra ha accompagnato i cambiamenti nella vita domestica delle donne italiane."
   ],
