   "sez": "adolescenti",
   "titolo": "Un esperimento per capire la scienza delle immagini residue",
   "orig": "Experiment: Discover the science behind afterimages",
   "lead": "Science News Explores propone un esperimento per osservare le immagini residue, un fenomeno visivo che permette di capire come le diverse cellule a cono della retina reagiscono ai vari colori. L'attività è pensata per far scoprire ai più giovani i meccanismi della percezione visiva attraverso l'osservazione diretta. Lo riferisce Science News Explores.",
   "more": [
    "Le cellule a cono sono i recettori dell'occhio responsabili della visione dei colori, sensibili a diverse lunghezze d'onda della luce. Le immagini residue si formano quando questi recettori si affaticano dopo una fissazione prolungata, producendo un'immagine percepita subito dopo aver distolto lo sguardo."
   ],
