   "titolo": "Il powerlifter estone racconta come la dieta vegana ha risolto i suoi problemi di salute",
   "orig": "Vegan powerlifter says diet change solved his health problems",
   "lead": "Il powerlifter Gert Koovit sostiene che il passaggio a una dieta vegana, adottata nove anni fa, abbia risolto i suoi problemi articolari e di salute, aggiungendo che il suo recupero fisico è migliorato notevolmente da allora. Lo riferisce ERR News.",
   "more": [
    "Il powerlifting è una disciplina sportiva che consiste nel sollevare il massimo peso possibile in tre esercizi fondamentali: squat, panca e stacco da terra. La dieta vegana esclude ogni prodotto di origine animale e viene talvolta adottata da atleti per motivi di salute o convinzioni etiche."
   ],
