   "lead": "Per il secondo anno consecutivo la stagione influenzale sembra essere partita in anticipo in Inghilterra: secondo l'UKHSA, nella settimana dal 28 settembre al 4 ottobre il tasso di positività ai test è salito al 6,5%, e i ricoveri ospedalieri per influenza hanno raggiunto 1,97 per 100.000 abitanti, i più alti mai registrati in questo periodo dell'anno secondo i medici dell'NHS. Lo riferisce The BMJ.",
