   "lead": "The BMJ denuncia come la mancanza di considerazioni su equità, diversità, inclusione e accessibilità minacci l'integrità scientifica ed etica della ricerca sanitaria, citando come esempio l'esclusione di pazienti neri dagli studi sul cancro e quella, spesso intenzionale, di persone in gravidanza o con disabilità cognitive dagli studi che potrebbero maggiormente avvantaggiarle. Lo riferisce The BMJ.",
