   "lead": "L'ex difensore Pietro Vierchowod, doppio ex della sfida tra Como e Roma, racconta in un'intervista a la Repubblica il suo passato nei due club e commenta la partita in arrivo: gli sarebbe piaciuto marcare Malen, mentre ritiene che Fabregas rischi troppo nelle ripartenze e avrebbe bisogno di un allenatore come Deschamps; il suo pronostico è un pareggio per 1-1, aggiungendo che un 4-4 non sarebbe calcio ma «un mucchio di errori». Lo riferisce la Repubblica.",
