   "lead": "Dopo la riapertura del suo panificio, il pizzaiolo romano Gabriele Bonci ha introdotto pizze condite esclusivamente con ingredienti vegetali al Panificio Bonci, considerato tra i più famosi d'Italia. Il pizzaiolo ha spiegato la scelta mettendo in relazione i costi delle materie prime, la volontà di sperimentare e un impegno di tipo sociale. Lo riferisce Gambero Rosso.",
