   "sez": "mondo",
   "titolo": "Polonia, la polizia ferma altri adolescenti dopo gli attacchi con coltello nelle scuole",
   "orig": "Polish police detain more teens following school knife attacks amid fears of further incidents",
   "lead": "La polizia polacca ha fermato altri adolescenti nell'ambito delle indagini sui due attacchi con coltello avvenuti in scuole del paese, mentre cresce il timore di nuovi episodi. Secondo Egypt Independent, le forze dell'ordine hanno fermato complessivamente 76 persone in tutto il paese e controllato quasi 50mila scuole per prevenire ulteriori violenze. Venerdì molte scuole avevano rafforzato la sicurezza, alcune sospendendo le lezioni, mentre numerosi genitori hanno scelto comunque di non tenere a casa i figli nonostante le voci online in circolazione.",
   "more": [
    "La Polonia ha visto negli ultimi giorni un'ondata di allerta nel sistema scolastico dopo due episodi di violenza con armi da taglio, che hanno spinto le autorità a un'azione di controllo capillare nelle scuole per prevenire ulteriori attacchi ed evitare il panico tra le famiglie."
   ],
