   "lead": "L'esercito centrafricano ha annunciato di aver condotto sabato attacchi aerei e operazioni terrestri contro gruppi armati nella prefettura della Vakaga, nel nord-est del paese, vicino alle frontiere con Ciad e Sudan, per prevenire un attacco ritenuto imminente.",
