   "titolo": "Camerun, un anno dopo il discorso di Maroua, il vuoto del settennato di Paul Biya",
   "orig": "Paul Biya, un an après le discours de campagne à Maroua, le grand vide d’un septennat fantôme",
   "lead": "Un anno dopo il discorso con cui il 7 ottobre 2025 Paul Biya si rivolgeva alle popolazioni del nord del Camerun durante il suo comizio a Maroua, promettendo rinnovamento e un ruolo centrale per i giovani, il bilancio del suo mandato viene descritto da Mimi Mefo Info come un vuoto politico. In parallelo, l'analista Ntimbane Bomo sostiene che il Consiglio costituzionale non abbia mai formalmente proclamato Biya vincitore delle elezioni, definendo la proclamazione priva di un potere sovrano e indiscutibile.",
   "more": [
    "Paul Biya è il presidente del Camerun da decenni, uno dei capi di stato più longevi al mondo. Il Consiglio costituzionale camerunese è l'organo che valida i risultati elettorali presidenziali, le cui decisioni restano spesso oggetto di contestazione da parte dell'opposizione."
   ],
