   "lead": "In Ungheria domenica il tempo migliora e in gran parte del paese cessano le piogge, con il sole che fa capolino in alcune zone. Nella parte orientale del paese, invece, il cielo resterà coperto e le condizioni resteranno instabili. La previsione riguarda l'intero territorio nazionale, segnando un cambiamento rispetto alle giornate precedenti caratterizzate da maltempo diffuso. Lo riferisce Telex English.",
