   "lead": "Il servizio sanitario del Nord della Norvegia deve tagliare mezzo miliardo di corone, ma la decisione di Helse Nord di assumere un nuovo consulente ha suscitato critiche. Il politico del Frp Kristian August Eilertsen ha dichiarato che questa scelta porta il sistema sanitario della regione nella direzione sbagliata, in un momento di forti ristrettezze economiche per il settore. Lo riferisce NRK.",
