   "lead": "Fatima Ezzahra El Mansouri è entrata nella seconda settimana di negoziati per formare il prossimo governo del Marocco senza che sia stata ancora annunciata una coalizione, mentre le trattative passano dalle consultazioni politiche generali alle questioni più spinose su chi entrerà nel governo, quali ministeri otterrà e come sarà strutturato il nuovo gabinetto, con la scadenza del bilancio fissata per il 20 ottobre. Il re Mohammed VI l'ha nominata capo del governo a settembre. Lo riferisce Hespress English.",
