   "lead": "La rassegna settimanale di notizie dalla Slovacchia segnala la chiusura temporanea delle porte del castello di Čachtice, legato alla leggenda della Contessa Insanguinata, oltre a una nuova sconfitta legale per il ministro dell'interno e la vittoria di un'azienda slovacca di un contratto con la NATO. Il digest include anche suggerimenti sugli eventi del fine settimana nel paese. Lo riferisce The Slovak Spectator.",
