   "lead": "A Nuku'alofa, Tonga, è stato pubblicato un avviso pubblico relativo al sistema di gestione ambientale e sociale del Matanataki Pacific Fund 1, promosso da Enyorra Private Equity e Matanataki Pte Ltd. Il documento è disponibile online e in copia cartacea presso il Ministero per la meteorologia, l'energia, l'informazione, la gestione dei disastri, l'ambiente, il cambiamento climatico e le comunicazioni, per la consultazione pubblica. Lo riferisce Matangi Tonga.",
