   "titolo": "Gambia: la difesa contesta la competenza del tribunale militare nel caso Manjang",
   "orig": "Military Tribunal ‘lacks competence’ to try Sanna Manjang, defence challenges court martial jurisdiction",
   "lead": "La difesa dell'ex tenente colonnello Sanna Manjang ha presentato una sfida giurisdizionale davanti al giudice Omar Cham del Tribunale Militare Generale, sostenendo che la corte non ha competenza a processarlo poiché avrebbe cessato di essere membro delle Forze Armate del Gambia quasi un decennio fa. Lo Stato, rappresentato dal direttore del pubblico ministero A.M. Yusuf, si è opposto con forza, sostenendo che Manjang è rimasto soggetto alla legge militare durante la sua lunga assenza. Il procedimento è iniziato con la presentazione dei membri della corte. Lo riferisce The Point.",
