   "lead": "Il Fondo di solidarietà per la salvaguardia della patria (FSSP) del Niger ha investito 58.803.729.545 franchi CFA nella sicurezza in tre anni, una cifra destinata al rafforzamento delle capacità delle Forze di difesa e sicurezza impegnate contro il terrorismo. Tale importo rappresenta l'82,6% delle risorse totali mobilizzate dal fondo. Il bilancio è stato presentato pubblicamente, come riportato dal quotidiano beninese La Nouvelle Tribune, che ne descrive la portata nel contesto della lotta antiterrorismo condotta dalle autorità nigerine. Lo riferisce La Nouvelle Tribune.",
