   "titolo": "Trump: «È ora che l'Ucraina abbia un nuovo presidente». Kiev respinge l'accusa",
   "orig": "Trump says Ukraine needs a new leader after diesel deal with Russia",
   "lead": "Un giorno dopo aver annunciato l'intesa con Vladimir Putin per l'acquisto di diesel russo, Donald Trump ha detto che è «ora che l'Ucraina abbia un nuovo presidente», sostenendo che Volodymyr Zelensky non ha fatto abbastanza per chiudere la guerra e attribuendogli la responsabilità dei prezzi alti dei carburanti negli Stati Uniti. Il presidente americano ha anche avvertito Kiev di fermare gli attacchi alle raffinerie russe che forniranno diesel a Washington.",
   "more": [
    "Secondo il Guardian, Trump non ha fornito prove a sostegno dell'accusa a Zelensky e la sua richiesta arriva mentre l'Ucraina subisce nuovi attacchi russi alle infrastrutture energetiche, alla vigilia dell'inverno.",
    "La prima ministra estone Kristen Michal ha criticato dall'altro fronte l'intesa Usa-Russia, dicendo che «gli accordi con i dittatori sono la strada per l'inferno», riferisce ERR News.",
    "Secondo l'esercito ucraino, dall'inizio dell'invasione russa nel febbraio 2022 le perdite tra le fila di Mosca avrebbero superato il milione e mezzo di soldati, cifra diffusa da Kyiv e non verificabile in modo indipendente."
   ],
