   "id": "delhi",
   "sez": "prima",
   "titolo": "India, liberati i leader del movimento «Cockroach» prima di una nuova protesta a Delhi",
   "orig": "Delhi braces for more protests as 'cockroach' group's leaders released",
   "lead": "Un tribunale indiano ha ordinato il rilascio, dopo circa un giorno di detenzione, dei leader del movimento «Cockroach», tra cui il fondatore del Cjp Abhijeet Dipke, fermati a Nuova Delhi alla vigilia di una grande manifestazione. Il gruppo chiede le dimissioni del capo della commissione elettorale indiana e si prepara a una nuova protesta il 12 ottobre.",
