   "titolo": "La «chef residency», un'idea arrivata da Londra",
   "testo": "La formula per cui un ristorante ospita per un periodo limitato uno chef diverso da quello titolare è nata nei locali londinesi ed è arrivata solo di recente in Italia, dove resta ancora un esperimento di nicchia.",
   "nota": "Curiosità di cronaca gastronomica, non una classifica di locali."
